51	            String telephone = OwnerTelephone.toE164(request.getTelephone());
52	            if (telephone == null) {
53	                errors.add("telephone");
54	            }
55	            else {
56	                request.setTelephone(telephone);
57	            }
58	        }
59	        // Email is optional. When present it must be syntactically valid; it is normalized to
60	        // lower case so it is stored and returned lower-cased.
